            if grid[i][c] == 0:
                out[i][c] = 1

        # Where a ray crosses a perpendicular line of 2s, mark the
        # neighboring cells around the crossing.
        crossings = []
        for j in range(w):
            if grid[r][j] == 2 and j != c:
                if (r > 0 and grid[r-1][j] == 2) or (r+1 < h and grid[r+1][j] == 2):
                    crossings.append((r, j))
        for i in range(h):
            if grid[i][c] == 2 and i != r:
                if (c > 0 and grid[i][c-1] == 2) or (c+1 < w and grid[i][c+1] == 2):
                    crossings.append((i, c))

        for cr, cc in crossings:
            for i in range(cr - 1, cr + 2):
                for j in range(cc - 1, cc + 2):
                    if 0 <= i < h and 0 <= j < w and grid[i][j] == 0:
                        out[i][j] = 1
            # The cells beside the crossing on the existing 2-line are
            # colored as well.
